  translate(0, 0, -200);

  rotateX(radians(angle));
  rotateY(radians(angle));

  drawHeart(0, 0, 0, 0);

  angle += 0.5;
}

function drawHeart(xCoor, yCoor, zCoor, depth) {
  if (depth > 4) return;

  stroke(255, 0, 0);
  strokeWeight(1.5);
  fill(255, 0, 0, 150);
  noFill();

  push();
  translate(xCoor, yCoor, zCoor);

  box(branchLength, 2, branchLength);

  pop();

