    let childAngle = TWO_PI / childCount * i;
    let childX = branchLength * sin(childAngle);
    let childY = 0;
    let childZ = branchLength * cos(childAngle);

    push();
    translate(childX, childY, childZ);
    rotateZ(childAngle);

    drawHeart(0, 0, 0, depth + 1);

    pop();
  }
}
