// Function to create a shared memory segment
void create_shared_memory(int& sem_id, std::string message) {
    using namespace boost::interprocess;

    // Create a shared memory segment
    shared_memory_object shm(create_only, "SharedMemory", read_write);
    shm.truncate(1024); // Size of the memory segment

    // Map the shared memory
    mapped_region region(shm, read_write);

    // Create message queue
    message_queue msg_queue(open_only, "MyMessageQueue");

    // Send message to message queue
    std::string message2 = "Hello from child process";
    std::pair<std::size_t, std::size_t> message_size_pair = msg_queue.send(message2.c_str(), message2.size());

    // Create a semaphore
    boost::interprocess::bariarian_semaphore* sem = new boost::interprocess::bariarian_semaphore(shm, 1);

    // Wait for other process to create shared memory
    while (!shm.exists()) {
        sem->wait();
    }

    // Delete semaphore
    delete sem;

    // Set shared memory size to 0
    shm.truncate(0);

    std::cout << "Child process finished." << std::endl;
