double integral(int numThreads, int numPoints, int method) {
    double integral = 0;
    double h = 1.0 / numPoints;
    double a = 0;
    double b = 1;

    switch (method) {
        case 0: // прямоугольники
            for (int i = 0; i < numPoints; i++) {
