            }
            break;
        case 2: // парабол (метод Симпсона)
            for (int i = 0; i < numPoints - 1; i++) {
                integral += h / 3 * (a + i * h) + 2 * h / 3 * (a + (i + 1) * h) + h / 3 * (a + (i + 2) * h);
            }
            break;
    }
    return integral;
}

