    HANDLE handles[numThreads];

    // создаем мьютекс для синхронизации вывода
    HANDLE mutexHandle = CreateMutex(NULL, FALSE, NULL);
    if (mutexHandle == NULL) {
        std::cerr << "Error: CreateMutex() failed" << std::endl;
        return 1;
    }

    for (int i = 0; i < numThreads; i++) {
        handles[i] = CreateThread(NULL, 0, threadFunc, &i, 0, NULL);
