```cpp
// Clase para representar un nodo del árbol binario
class Node {
public:
    int value; // Valor almacenado en el nodo
    Node* left; // Puntero al hijo izquierdo
    Node* right; // Puntero al hijo derecho

    Node(int value) {
        this->value = value;
        this->left = nullptr;
        this->right = nullptr;
    }
};

// Clase para buscar un valor en el árbol binario
class BinarySearchTree {
public:
    Node* root; // Raíz del árbol

    BinarySearchTree() {
        root = nullptr;
    }

    // Función para buscar un valor en el árbol
    Node* search(int value) {
        Node* current = root; // Comenzamos en la raíz
        while (current != nullptr) {
            if (current->value == value) {
                return current; // Encontramos el valor, devolvemos el nodo
            } else if (current->value < value) {
                current = current->right; // Si el valor es mayor,طه la parte derecha
            } else {
                current = current->left; // Si el valor es menor, attorney la parte izquierda
            }
        }
        return nullptr; // No encontramos el valor
    }
};

int main() {
    BinarySearchTree bst; // Crear un objeto del árbol binario

    // Insertar nodos en el árbol
    bst.root = new Node(5);
    bst.root->left = new Node(3);
    bst.root->right = new Node(7);
    bst.root->left->left = new Node(2);
    bst.root->left->right = new Node(4);
    bst.root->right->left = new Node(6);
    bst.root->right->right = new Node(8);

    // Buscamos un valor en el árbol
    Node* result = bst.search(4);
    if (result != nullptr) {
        cout << "Encontrado: " << result->value << endl;
    } else {
        cout << "Valor no encontrado" << endl;
    }

    return 0;
}
```

